/**
 * Unit tests for Vector3D.crossProduct
 */
public class Vector3D_crossProduct_TriageGen4Test {

    private static final double EPSILON = 1e-12;



    @Test
    public void testCrossProduct_AntiCommutative() {
        Vector3D v1 = new Vector3D(1, 2, 3);
        Vector3D v2 = new Vector3D(4, 5, 6);

        Vector3D res1 = Vector3D.crossProduct(v1, v2);
        Vector3D res2 = Vector3D.crossProduct(v2, v1);

        // v1 x v2 = -(v2 x v1)
        assertVectorEquals(res1.negate(), res2);
    }











    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        Assert.assertEquals("X coordinate mismatch", expected.getX(), actual.getX(), EPSILON);
        Assert.assertEquals("Y coordinate mismatch", expected.getY(), actual.getY(), EPSILON);
        Assert.assertEquals("Z coordinate mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}

